async function initialize(){
 if(!Bun.env.DATABASE_URL)throw Error('DATABASE_URL absent');
 const ddl=[
 'CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY,email text UNIQUE NOT NULL,handle text UNIQUE NOT NULL,password_hash text NOT NULL,xp integer NOT NULL DEFAULT 0,referred_by uuid REFERENCES users(id),referral_awarded boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now())',
 'CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at timestamptz NOT NULL)',
 'CREATE TABLE IF NOT EXISTS projects (id text PRIMARY KEY,title text NOT NULL,description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now())',
 "CREATE TABLE IF NOT EXISTS missions (id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),title text NOT NULL,category text NOT NULL,difficulty text NOT NULL,xp integer NOT NULL CHECK(xp>=0),brief text NOT NULL,deliverable text NOT NULL,status text NOT NULL DEFAULT 'open')",
 "CREATE TABLE IF NOT EXISTS submissions (id uuid PRIMARY KEY,mission_id text NOT NULL REFERENCES missions(id),user_id uuid NOT NULL REFERENCES users(id),body text NOT NULL,evidence_url text,status text NOT NULL DEFAULT 'pending',reviewer_note text,created_at timestamptz NOT NULL DEFAULT now(),reviewed_at timestamptz,UNIQUE(mission_id,user_id))",
 'CREATE TABLE IF NOT EXISTS reward_events (id uuid PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id),submission_id uuid UNIQUE REFERENCES submissions(id),kind text NOT NULL,xp integer NOT NULL CHECK(xp>=0),created_at timestamptz NOT NULL DEFAULT now())',
 "CREATE TABLE IF NOT EXISTS workpackets (id uuid PRIMARY KEY,submission_id uuid UNIQUE NOT NULL REFERENCES submissions(id),project_id text NOT NULL REFERENCES projects(id),status text NOT NULL DEFAULT 'triage_ready',created_at timestamptz NOT NULL DEFAULT now())",
 'CREATE TABLE IF NOT EXISTS sponsor_leads (id uuid PRIMARY KEY,name text NOT NULL,email text NOT NULL,project text NOT NULL,budget text NOT NULL,description text NOT NULL,created_at timestamptz NOT NULL DEFAULT now())',
 'CREATE TABLE IF NOT EXISTS rate_limits (key text PRIMARY KEY,bucket bigint NOT NULL,count integer NOT NULL DEFAULT 0)',
 'CREATE TABLE IF NOT EXISTS operator_sessions (token_hash text PRIMARY KEY,expires_at timestamptz NOT NULL)',
 'CREATE TABLE IF NOT EXISTS revalidations (id uuid PRIMARY KEY,workpacket_id uuid NOT NULL UNIQUE REFERENCES workpackets(id) ON DELETE CASCADE,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,resolved boolean NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now())',
 "CREATE TABLE IF NOT EXISTS bridge_events (id uuid PRIMARY KEY,submission_id uuid REFERENCES submissions(id) ON DELETE CASCADE,workpacket_id uuid,project_id text NOT NULL REFERENCES projects(id),event_type text NOT NULL,idempotency_key text NOT NULL UNIQUE,evidence_url text,source text NOT NULL DEFAULT 'platform',created_at timestamptz NOT NULL DEFAULT now())",
 'CREATE INDEX IF NOT EXISTS ix_bridge_events_project ON bridge_events(project_id,created_at DESC)',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS repository text',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS artifact_url text',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS qa_evidence_url text',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS release_url text',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS execution_trace_id text',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now()',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS lease_owner text',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS lease_expires_at timestamptz',
 'ALTER TABLE workpackets ADD COLUMN IF NOT EXISTS verification_receipt_url text',
 'CREATE INDEX IF NOT EXISTS ix_workpackets_status ON workpackets(status,updated_at DESC)',
 'CREATE INDEX IF NOT EXISTS ix_submissions_user ON submissions(user_id,created_at DESC)',
 'CREATE INDEX IF NOT EXISTS ix_submissions_status ON submissions(status,created_at DESC)'
 ];
 for(const q of ddl) await sql.unsafe(q);
 await sql`INSERT INTO projects(id,title,description) VALUES('proofloom-lab','Proofloom Product Lab','The live, self-contained Proofloom product experience. No unrelated private repository access is required.') ON CONFLICT(id) DO NOTHING`;
 for(const [id,title,category,difficulty,xp,brief,deliverable] of seeds)
  await sql`INSERT INTO missions(id,project_id,title,category,difficulty,xp,brief,deliverable) VALUES(${id},'proofloom-lab',${title},${category},${difficulty},${xp},${brief},${deliverable}) ON CONFLICT(id) DO NOTHING`;
}
async function ready(){if(!startup)startup=initialize().catch(e=>{startup=undefined;throw e});await startup;}
async function user(c:any){const token=getCookie(c,COOKIE);if(!token)return null;const result=await sql`SELECT u.id,u.handle,u.email,u.xp,u.created_at FROM sessions s JOIN users u ON u.id=s.user_id WHERE s.token_hash=${digest(token)} AND s.expires_at>now() LIMIT 1`;return result[0]||null;}
async function allowed(c:any,action:string,limit:number,period:number){const ip=(c.req.header('cf-connecting-ip')||c.req.header('x-real-ip')||c.req.header('x-forwarded-for')||'unknown').split(',')[0];const bucket=Math.floor(Date.now()/(period*1000));const key=digest(action+':'+ip+':'+bucket);const rows=await sql`INSERT INTO rate_limits(key,bucket,count) VALUES(${key},${bucket},1) ON CONFLICT(key) DO UPDATE SET count=rate_limits.count+1 RETURNING count`;return rows[0].count<=limit;}
function sameOrigin(c:any){const origin=c.req.header('origin');if(!origin)return true;try{return new URL(origin).host===new URL(c.req.url).host}catch{return false}}
function httpsLink(s:string){if(!s)return true;try{return new URL(s).protocol==='https:'}catch{return false}}
function adminKey(s:string){const secret=Bun.env.OPERATOR_REVIEW_KEY||'';return secret.length>=32&&secret.length===s.length&&timingSafeEqual(Buffer.from(secret),Buffer.from(s));}
async function bridgeAuth(c:any,role:'agent'|'verifier'='agent'){
 const secret=role==='verifier'?Bun.env.VERIFIER_API_KEY:Bun.env.BRIDGE_API_KEY;
 const supplied=(c.req.header('authorization')||'').replace(/^Bearer\s+/i,'');
 if(typeof secret==='string'&&secret.length>=32&&supplied.length===secret.length&&timingSafeEqual(Buffer.from(supplied),Buffer.from(secret)))return true;
 return await verifyActionsJwt(supplied,role);
}
const OPER_COOKIE='__Host-proofloom-operator';
async function operatorSession(c:any){const token=getCookie(c,OPER_COOKIE);if(!token)return false;const rows=await sql`SELECT token_hash FROM operator_sessions WHERE token_hash=${digest(token)} AND expires_at>now() LIMIT 1`;return rows.length>0;}
async function operatorAllowed(c:any,key?:string){return await operatorSession(c)||(key!==undefined&&adminKey(key));}
function bridgeRepository(){const r=(Bun.env.BRIDGE_REPOSITORY||'').trim();return /^[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+$/.test(r)?r:null;}
// Verify GitHub evidence server-side before a runner may advance a WorkPacket.
// GitHub API addresses are constructed from our single allowed repository, never from user URLs.
async function verifiedGitHubEvidence(workpacketId:string,type:string,url:string,packet:any){
 const repo=bridgeRepository();if(repo!=='Noetfield-Systems/Proofloom-Genesis'||packet.repository!==repo)return false;
 const prefix='https://github.com/'+repo;
 async function get(path:string){const r=await fetch('https://api.github.com/repos/'+repo+path,{headers:{Accept:'application/vnd.github+json','User-Agent':'proofloom-bridge/0.4'},signal:AbortSignal.timeout(8000)});if(!r.ok)throw Error('github_evidence_http_'+r.status);return r.json();}
 const exact=(pattern:RegExp)=>pattern.exec(url);
 if(type==='workpacket.dispatched'){
  const m=exact(new RegExp('^'+prefix.replaceAll('.','\\.')+'/issues/(\\d+)$'));if(!m)return false;
  const issue=await get('/issues/'+m[1]);return !issue.pull_request&&(issue.body||'').includes('proofloom-workpacket:'+workpacketId);
 }
 if(type==='implementation.ready'){
  const m=exact(new RegExp('^'+prefix.replaceAll('.','\\.')+'/pull/(\\d+)$'));if(!m)return false;
  const pr=await get('/pulls/'+m[1]);
  return pr.base?.ref==='main'&&pr.head?.repo?.full_name===repo&&pr.head?.ref==='proofloom/translation-'+workpacketId.replaceAll('-','').slice(0,18)&&(pr.body||'').includes('Source WorkPacket: '+workpacketId);
 }
 if(type==='qa.completed'){
  const m=exact(new RegExp('^'+prefix.replaceAll('.','\\.')+'/pull/(\\d+)/checks$'));if(!m||packet.artifact_url!==prefix+'/pull/'+m[1])return false;
  const pr=await get('/pulls/'+m[1]);const check=await get('/commits/'+pr.head.sha+'/check-runs?per_page=100');
  return (check.check_runs||[]).some((x:any)=>x.name==='syntax-and-contracts'&&x.status==='completed'&&x.conclusion==='success');
 }
 if(type==='release.reported'){
  const m=exact(new RegExp('^'+prefix.replaceAll('.','\\.')+'/commit/([0-9a-f]{40})$'));if(!m||!packet.artifact_url||!Bun.env.RAILWAY_GIT_COMMIT_SHA||Bun.env.RAILWAY_GIT_COMMIT_SHA!==m[1])return false;
  const pm=new RegExp('^'+prefix.replaceAll('.','\\.')+'/pull/(\\d+)$').exec(packet.artifact_url);if(!pm)return false;
  const pr=await get('/pulls/'+pm[1]);return pr.merged===true&&pr.merge_commit_sha===m[1]&&!!packet.qa_evidence_url;
 }
 return false;
}
async function bridgeEvent(tx:any,submissionId:string|null,packetId:string|null,projectId:string,eventType:string,idempotency:string,evidence:string|null=null,source='platform'){
 await tx`INSERT INTO bridge_events(id,submission_id,workpacket_id,project_id,event_type,idempotency_key,evidence_url,source) VALUES(${crypto.randomUUID()},${submissionId},${packetId},${projectId},${eventType},${idempotency},${evidence},${source}) ON CONFLICT(idempotency_key) DO NOTHING`;
}

async function login(c:any,id:string){const t=crypto.randomUUID()+'.'+crypto.randomUUID();await sql`INSERT INTO sessions(token_hash,user_id,expires_at) VALUES(${digest(t)},${id},now()+interval '30 days')`;setCookie(c,COOKIE,t,{httpOnly:true,secure:true,sameSite:'Lax',path:'/',maxAge:2592000});}
async function totals(){const rows=await sql`SELECT (SELECT count(*)::int FROM users) builders,(SELECT count(*)::int FROM submissions) submissions,(SELECT count(*)::int FROM submissions WHERE status='accepted') accepted,(SELECT count(*)::int FROM missions WHERE status='open') missions`;return rows[0];}

