const nav=[['/missions','Missions'],['/studio','Vibe Studio'],['/community','Community'],['/activity','Activity'],['/academy','Academy'],['/opportunities','Opportunities'],['/rewards','Rewards']];
function Shell({u,active,notice,children}:any){return <html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><meta name="theme-color" content="#080b12"/><meta name="description" content="Proofloom — Build it. Prove it. Earn it. The human x AI builder economy."/><title>Proofloom — Build it. Prove it. Earn it.</title><style>{CSS}{PREMIUM_CSS}</style></head><body><div class="shell-topline"><div class="wrap"><span>PROOFLOOM / GENESIS NETWORK</span><span>Build it. Prove it. Earn it.</span></div></div><a class="skip-link" href="#content">Skip to main content</a><header class="nav"><div class="wrap navin"><a class="brand" href="/">proof<b>loom</b><small style="font-size:10px;letter-spacing:1px;color:#9fb2a7;padding-left:7px">BETA</small></a><nav class="navlinks">{nav.map(([path,label])=><a href={path} class={active===path?'active':''}>{label}</a>)}</nav><div class="auth">{u?<><a class="btn ghost sm" href="/profile">@{u.handle}</a><form action="/logout" method="post" style="display:inline"><button class="btn sm">Sign out</button></form></>:<><a class="btn ghost sm" href="/login">Log in</a><a class="btn sm" href="/join">Join Genesis ↗</a></>}</div></div><nav class="mobile" aria-label="Mobile navigation">{nav.map(([path,label])=><a href={path}>{label}</a>)}</nav></header><main class="wrap" id="content">{notice&&<div class="notice">{notice}</div>}{children}</main><footer class="wrap footer"><div><a class="brand" href="/">proof<b>loom</b></a><div>An independent human × AI builder economy · 2026</div></div><div><a href="/whitepaper">Whitepaper</a> · <a href="/privacy">Privacy</a> · <a href="/terms">Terms</a> · <a href="/sponsors">Sponsors</a> · <a href="/operator">Operator</a><div>XP is not money. No token, funded payout or active claim is represented.</div></div></footer></body></html>}
function MissionCard({m}:any){return <a class="card" href={'/mission/'+m.id}><span class="mission-card-number">{m.id.toUpperCase()}</span><div class="meta">{m.category} · {m.difficulty}</div><h3>{m.title}</h3><p>{m.brief}</p><div class="bottom"><span>{m.xp} XP after acceptance</span><span class="arrow">↗</span></div></a>}
// Language negotiation precedes the database middleware. Language selection is persisted
// in a same-site cookie and reflected in <html lang>, dir and all platform UI copy.
app.use('*', async(c,next)=>{
 const explicit=c.req.query('lang');
 const cookie=getCookie(c,'proofloom_lang');
 const chosen=selectLocale(explicit||cookie||c.req.header('accept-language'));
 await next();
 const type=c.res.headers.get('content-type')||'';
 if(type.includes('text/html')){
  const original=await c.res.text();
  const request=new URL(c.req.url);
  const adjusted=localizeHtml(original,chosen,request.pathname+request.search);
  const headers=new Headers(c.res.headers);headers.set('Content-Type','text/html; charset=UTF-8');headers.set('Vary','Accept-Language, Cookie');headers.set('Cache-Control','private, no-store');
  c.res=new Response(adjusted,{status:c.res.status,headers});
 } else if(type.includes('text/plain') && chosen !== 'en' && !c.req.path.startsWith('/api/')) {
  // Translate short platform-owned validation errors; preserve status and never touch JSON or submitted content.
  const original=await c.res.text();
  const headers=new Headers(c.res.headers);headers.set('Content-Type','text/plain; charset=UTF-8');headers.set('Vary','Accept-Language, Cookie');
  c.res=new Response(localizePlain(original,chosen),{status:c.res.status,headers});
 }
 if(explicit && chosen===selectLocale(explicit))setCookie(c,'proofloom_lang',chosen,{httpOnly:true,sameSite:'Lax',secure:new URL(c.req.url).protocol==='https:',path:'/',maxAge:31536000});
});
app.get('/language',c=>{
 const lang=selectLocale(c.req.query('lang'));
 const dest=c.req.query('return_to')||'/';
 if(!dest.startsWith('/')||dest.startsWith('//')||dest.includes('\\'))return c.text('Invalid destination',400);
 setCookie(c,'proofloom_lang',lang,{httpOnly:true,sameSite:'Lax',secure:new URL(c.req.url).protocol==='https:',path:'/',maxAge:31536000});
 return c.redirect(dest);
});
app.use('*',async(c,next)=>{try{await ready();await next()}catch(e:any){console.error('proofloom_runtime',e?.message||'unknown');if(c.req.path==='/health')return c.json({status:'degraded',db:false},503);return c.html(<Shell u={null} active=""><div class="subhero"><h2>Temporarily unavailable.</h2><p>The request was not accepted. Please retry.</p></div></Shell>,503)}});
app.get('/health',c=>c.json({status:'ok',database:true,version:'genesis-0.5'}));
app.get('/',async c=>{const u=await user(c),s=await totals(),missions=await sql`SELECT * FROM missions WHERE status='open' ORDER BY id LIMIT 6`;return c.html(<Shell u={u} active="" notice={c.req.query('notice')}><div class="hero"><div><div class="eyebrow">GENESIS / THE HUMAN × AI BUILDER NETWORK</div><h1>Build it.<br/><em>Prove it.</em><br/>Earn it.</h1><p>Turn ideas, prompts and real contributions into better software, verified skills and new opportunities. No coding experience required.</p><div class="actions"><a class="btn" href={u?'/missions':'/join'}>{u?'Explore missions':'Become a Genesis builder'} ↗</a><a class="btn ghost" href="/missions">Explore live missions</a></div><div class="credibility-note">Free to join. No crypto wallet required. Your first mission is waiting.</div></div><div class="heroart"><div class="artheader"><span class="window-dots"><i></i><i></i><i></i></span><span class="window-title">PROOFLOOM / CONTRIBUTION FLOW</span></div><div class="pipeline-heading"><strong>From contribution to proof</strong><span class="pipeline-tag">GENESIS BETA</span></div><div class="artrows"><div class="artrow"><span class="num">01</span><div><strong>Human idea</strong><small>Prompt · Feedback · Code · Test</small></div><span class="art-step-status">Submit</span></div><div class="artrow"><span class="num">02</span><div><strong>Real contribution</strong><small>Submission · Review · Evidence</small></div><span class="art-step-status">Review</span></div><div class="artrow"><span class="num">03</span><div><strong>Verified recognition</strong><small>Proof · XP · Opportunity</small></div><span class="art-step-status">Record</span></div></div><div class="artbottom"><strong>Independent release verification is a separate step.</strong><span>Agent PR dispatch is not active until its repository credentials are configured.</span></div></div></div><div class="metrics"><div><strong>{s.builders}</strong><span>Registered builders</span></div><div><strong>{s.submissions}</strong><span>Real submissions</span></div><div><strong>{s.accepted}</strong><span>Accepted contributions</span></div><div><strong>{s.missions}</strong><span>Open missions</span></div></div><section class="section"><div class="sectionhead"><div><div class="label">YOUR FIRST CONTRIBUTION</div><h2>Make something better.</h2><p>Test, design, code or create a prompt. Every useful contribution matters.</p></div><a class="btn ghost" href="/missions">All missions ↗</a></div><div class="grid">{missions.map((m:any)=><MissionCard m={m}/>)}</div></section><div class="feature-row"><div class="feature-tile"><div class="feature-index">01 / ACCESS</div><h3>Build without barriers</h3><p>Start with a prompt, test, translation or reproducible improvement. No wallet or developer setup required.</p></div><div class="feature-tile"><div class="feature-index">02 / EVIDENCE</div><h3>Every contribution has a record</h3><p>Track the review decision, source evidence and the next step without confusing XP with a shipped change.</p></div><div class="feature-tile"><div class="feature-index">03 / PROGRESS</div><h3>Real work, visible progress</h3><p>Approved ideas can become WorkPackets. Issues, pull requests and production releases appear only when evidenced.</p></div></div><section class="section"><div class="label">HOW IT WORKS</div><h2>From idea to verified work.</h2><div class="steps">{[['01','Discover','Choose a challenge for your skills.'],['02','Contribute','Share a test, prompt, design or fix.'],['03','Get reviewed','Follow evidence-based review status.'],['04','Grow','Earn XP only for accepted work.']].map(([n,t,d])=><div class="step"><small>{n}</small><h3>{t}</h3><p>{d}</p></div>)}</div></section><section class="banner"><div><div class="label" style="color:#376b43">SEASON 0 · GENESIS</div><h2>The future is built together.</h2><p>Help improve the very platform you are joining.</p></div><a class="btn" href="/join">Join the first wave ↗</a></section></Shell>)});
app.get('/missions',async c=>{
 const categories=['All','Feedback','Bug Hunter','Vibe Coding','Design','Testing','Learning'];
 const difficulties=['All','Beginner','Intermediate','Advanced'];
 const rawCategory=esc(c.req.query('category')||'All'),rawDifficulty=esc(c.req.query('difficulty')||'All');
 const category=categories.includes(rawCategory)?rawCategory:'All';
 const difficulty=difficulties.includes(rawDifficulty)?rawDifficulty:'All';
 const search=esc(c.req.query('search')||'').slice(0,80);
 const all=await sql`SELECT * FROM missions WHERE status='open' ORDER BY id`;
 const list=all.filter((m:any)=>(category==='All'||m.category===category)&&(difficulty==='All'||m.difficulty===difficulty)&&(!search||(m.title+' '+m.brief+' '+m.deliverable).toLowerCase().includes(search.toLowerCase())));
 const path=(cat:string)=>'/missions?'+new URLSearchParams({category:cat,difficulty,search}).toString();
 return c.html(<Shell u={await user(c)} active="/missions"><div class="subhero"><div class="label">DISCOVER / CONTRIBUTE / GROW</div><h2>Find your next contribution.</h2><p>Real tasks for explorers, prompt builders, testers, designers and developers. Find one that matches your skills.</p></div><div class="strip">{categories.map(x=><a class={'chip '+(category===x?'active':'')} href={path(x)}>{x}</a>)}</div><form class="mission-toolbar" action="/missions" method="get"><input type="hidden" name="category" value={category}/><div class="field"><label for="mission-search">Search missions</label><input id="mission-search" type="search" name="search" value={search} maxlength="80" placeholder="Try translation, onboarding, bug report..." autocomplete="off"/></div><div class="field"><label for="mission-difficulty">Difficulty</label><select id="mission-difficulty" name="difficulty">{difficulties.map(d=><option value={d} selected={d===difficulty}>{d}</option>)}</select></div><button class="btn" type="submit">Find missions ↗</button></form><div class="filter-summary"><span>{list.length} of {all.length} open missions</span>{(search||category!=='All'||difficulty!=='All')&&<a class="link" href="/missions">Clear filters ↗</a>}</div><div class="grid">{list.map((m:any)=><MissionCard m={m}/>)}</div>{list.length===0&&<div class="empty"><h3>No matching missions</h3><p>Try a different search or clear the filters to explore all open work.</p><a class="btn ghost" href="/missions">Show all missions</a></div>}</Shell>);
});
app.get('/mission/:id',async c=>{const m=(await sql`SELECT m.*,p.title AS project FROM missions m JOIN projects p ON p.id=m.project_id WHERE m.id=${c.req.param('id')} LIMIT 1`)[0];if(!m)return c.notFound();const u=await user(c),previous=u?await sql`SELECT status,reviewer_note FROM submissions WHERE user_id=${u.id} AND mission_id=${m.id}`:[];return c.html(<Shell u={u} active="/missions" notice={c.req.query('notice')}><div class="crumb"><a href="/missions">← All missions</a> / {m.category}</div><div class="subhero"><div class="label">{m.project} · {m.difficulty}</div><h2>{m.title}</h2><p>{m.brief}</p><span class="badge">{m.xp} XP after review</span></div><div class="two"><div class="panel"><h3>Objective</h3><p>{m.brief}</p><h3>What to submit</h3><p>{m.deliverable}</p>{previous.length&&previous[0].status!=='changes_requested'?<div class="notice">Status: {previous[0].status}. <a class="link" href="/profile">Track your contribution</a>.</div>:u?<form action="/submit" method="post"><input type="hidden" name="mission_id" value={m.id}/><div class="field"><label>Your contribution and reproducible evidence</label><textarea name="body" required minlength="25" maxlength="6000" placeholder={m.id==='q13'?'{"locale":"fa","key":"Missions","text":"ماموریت‌ها","why":"This more accurately describes the destination for Persian readers."}':'Explain exactly what you tested or built. Specificity is rewarded.'}></textarea></div><div class="field"><label>HTTPS evidence link (optional)</label><input type="url" name="evidence" placeholder="https://github.com/..."/></div><button class="btn">Submit for review ↗</button></form>:<div class="actions"><a class="btn" href={'/join?mission='+m.id}>Join to submit ↗</a><a class="btn ghost" href="/login">Log in</a></div>}</div><div class="panel"><div class="label">QUALITY STANDARD</div><h3>Show your work.</h3><p>Clear reproduction, concrete suggestions, code diffs and tests create value. Repetitive or vague submissions receive no XP.</p><h3>Lifecycle</h3><p>Submitted → Under review → Accepted, changes requested or rejected. Accepted work gets an independently accessible proof record and XP. Release is a separate state.</p><div class="fine">XP is off-chain and not a financial entitlement.</div></div></div></Shell>)});
app.get('/join',async c=>{if(await user(c))return c.redirect('/profile');return c.html(<Shell u={null} active=""><div class="formpage"><div class="label">GENESIS / SIGN UP</div><h2>Create your builder identity.</h2><p>No crypto wallet. No experience barrier.</p>{c.req.query('error')&&<div class="notice bad">{c.req.query('error')}</div>}<div class="panel"><form action="/register" method="post"><div class="field"><label>Public handle</label><input name="handle" pattern="[A-Za-z0-9_]+" minlength="3" maxlength="22" required placeholder="buildername"/></div><div class="field"><label>Email</label><input name="email" type="email" maxlength="200" required/></div><div class="field"><label>Password (12+ characters)</label><input name="password" type="password" minlength="12" maxlength="128" required/></div><div class="field"><label>Referral handle (optional)</label><input name="ref" value={c.req.query('ref')||''}/></div><label class="fine"><input type="checkbox" name="agree" value="yes" required/> I agree to the <a class="link" href="/terms">participation terms</a> and acknowledge the <a class="link" href="/privacy">privacy notice</a>.</label><button class="btn">Create account ↗</button><p class="fine">Email verification is not yet active. Tokens and paid bounties are not issued in Genesis beta.</p></form></div><p class="fine">Already a member? <a class="link" href="/login">Log in</a>.</p></div></Shell>)});
app.get('/login',async c=>{if(await user(c))return c.redirect('/profile');return c.html(<Shell u={null} active=""><div class="formpage"><div class="label">WELCOME BACK</div><h2>Log in.</h2>{c.req.query('error')&&<div class="notice bad">{c.req.query('error')}</div>}<div class="panel"><form action="/login" method="post"><div class="field"><label>Email</label><input name="email" type="email" required/></div><div class="field"><label>Password</label><input name="password" type="password" required/></div><button class="btn">Continue ↗</button></form></div></div></Shell>)});
app.post('/register',async c=>{if(!sameOrigin(c))return c.text('Forbidden',403);if(!await allowed(c,'signup',8,3600))return c.redirect('/join?error='+qp('Too many attempts.'));const b=await c.req.parseBody(),email=esc(b.email).toLowerCase(),handle=esc(b.handle).toLowerCase(),password=String(b.password||''),ref=esc(b.ref).toLowerCase();if(esc(b.agree)!=='yes')return c.redirect('/join?error='+qp('Please accept the participation terms.'));if(!/^[a-z0-9_]{3,22}$/.test(handle)||!/^\S+@\S+\.\S+$/.test(email)||password.length<12||password.length>128)return c.redirect('/join?error='+qp('Invalid email, handle or password.'));try{const parent=ref?await sql`SELECT id FROM users WHERE handle=${ref} AND handle<>${handle} LIMIT 1`:[];const id=crypto.randomUUID();const ph=await Bun.password.hash(password);await sql`INSERT INTO users(id,email,handle,password_hash,referred_by) VALUES(${id},${email},${handle},${ph},${parent[0]?.id||null})`;await login(c,id);return c.redirect('/profile?notice='+qp('Genesis profile created. Choose a mission.'));}catch(e:any){if(e?.code==='23505')return c.redirect('/join?error='+qp('Email or handle already exists.'));throw e}});
app.post('/login',async c=>{if(!sameOrigin(c))return c.text('Forbidden',403);if(!await allowed(c,'login',30,3600))return c.redirect('/login?error='+qp('Too many attempts.'));const b=await c.req.parseBody(),r=await sql`SELECT id,password_hash FROM users WHERE email=${esc(b.email).toLowerCase()} LIMIT 1`;if(!r.length||!await Bun.password.verify(String(b.password||''),r[0].password_hash))return c.redirect('/login?error='+qp('Invalid credentials.'));await login(c,r[0].id);return c.redirect('/profile')});
app.post('/logout',async c=>{if(!sameOrigin(c))return c.text('Forbidden',403);const token=getCookie(c,COOKIE);if(token)await sql`DELETE FROM sessions WHERE token_hash=${digest(token)}`;deleteCookie(c,COOKIE,{path:'/',secure:true});return c.redirect('/')});
app.post('/submit',async c=>{
 if(!sameOrigin(c))return c.text('Forbidden',403);
 const u=await user(c);if(!u)return c.redirect('/join');
 if(!await allowed(c,'submission:'+u.id,20,3600))return c.text('Rate limit reached',429);
 const b=await c.req.parseBody(),id=esc(b.mission_id),body=esc(b.body),evidence=esc(b.evidence);
 if(!/^q[0-9]{2}$/.test(id)||body.length<25||body.length>6000||evidence.length>700||!httpsLink(evidence))return c.text('Invalid contribution',400);
 const mission=(await sql`SELECT m.id,m.project_id FROM missions m WHERE m.id=${id} AND m.status='open' LIMIT 1`)[0];if(!mission)return c.text('Mission unavailable',404);
 let changed=false;
 try{await sql.begin(async tx=>{
  const prior=await tx`SELECT id,status FROM submissions WHERE mission_id=${id} AND user_id=${u.id} FOR UPDATE`;
  if(prior.length){if(prior[0].status!=='changes_requested')throw Error('A contribution already exists for this mission');
   await tx`UPDATE submissions SET body=${body},evidence_url=${evidence||null},status='pending',reviewer_note=null,reviewed_at=null,created_at=now() WHERE id=${prior[0].id}`;
   await bridgeEvent(tx,prior[0].id,null,mission.project_id,'contribution.revised','revision:'+prior[0].id+':'+crypto.randomUUID());changed=true;
  }else{const submissionId=crypto.randomUUID();await tx`INSERT INTO submissions(id,mission_id,user_id,body,evidence_url) VALUES(${submissionId},${id},${u.id},${body},${evidence||null})`;
   await bridgeEvent(tx,submissionId,null,mission.project_id,'contribution.submitted','submission:'+submissionId);}
 });return c.redirect('/profile?notice='+qp(changed?'Your revision was received for review.':'Contribution recorded. Review is pending.'));
 }catch(e:any){if(e?.code==='23505'||e?.message?.includes('already exists'))return c.redirect('/profile?notice='+qp('A contribution for this mission is already recorded.'));throw e}
});
app.get('/profile',async c=>{const u=await user(c);if(!u)return c.redirect('/join');const items=await sql`SELECT s.*,m.title,m.xp,w.id AS workpacket_id,w.status AS workpacket_status,w.release_url FROM submissions s JOIN missions m ON m.id=s.mission_id LEFT JOIN workpackets w ON w.submission_id=s.id WHERE s.user_id=${u.id} ORDER BY s.created_at DESC`;const refs=await sql`SELECT count(*)::int total,count(*) FILTER(WHERE referral_awarded)::int qualified FROM users WHERE referred_by=${u.id}`;return c.html(<Shell u={u} active="" notice={c.req.query('notice')}><div class="subhero"><div class="profile-hero"><div class="profile-avatar" aria-hidden="true">{u.handle.slice(0,1).toUpperCase()}</div><div><div class="label">YOUR BUILDER IDENTITY</div><h2>@{u.handle}</h2><span class="live-pill">Genesis profile</span></div></div><p>Your contributions, decisions and evidence-backed progress. <a class="link" href="/account">Account &amp; data settings ↗</a></p></div><div class="grid"><div class="panel"><div class="label">XP</div><div class="score">{u.xp}</div><p>Nontransferable, nonfinancial recognition.</p></div><div class="panel"><div class="label">YOUR SUBMISSIONS</div><div class="score">{items.length}</div><p>{items.filter((s:any)=>s.status==='accepted').length} accepted</p></div><div class="panel"><div class="label">QUALIFIED REFERRALS</div><div class="score">{refs[0].qualified}</div><p>{refs[0].total} joined; earn only after accepted work.</p></div></div><section class="section"><div class="sectionhead"><div><div class="label">CONTRIBUTION TIMELINE</div><h2>Your work.</h2></div><a class="btn" href="/missions">Open missions ↗</a></div>{items.length?<div class="panel"><table class="table"><thead><tr><th>Mission</th><th>Status</th><th>Reward</th><th>Proof</th></tr></thead><tbody>{items.map((s:any)=><tr><td>{s.title}<div class="fine">{new Date(s.created_at).toISOString().slice(0,10)}</div>{s.reviewer_note&&<div class="fine">Review: {s.reviewer_note}</div>}</td><td><span class={'badge '+s.status}>{s.status}</span></td><td>{s.status==='accepted'?s.xp+' XP':'—'}</td><td>{s.status==='accepted'?<><a class="link" href={'/proof/'+s.id}>Proof ↗</a>{s.workpacket_status==='release_verified'&&<div><a class="link" href={'/revalidate/'+s.workpacket_id}>Verify release ↗</a></div>}{s.workpacket_status&&<div class="fine">Development: {s.workpacket_status} · <a class="link" href={'/work/'+s.workpacket_id}>Timeline ↗</a></div>}</>:'—'}</td></tr>)}</tbody></table></div>:<div class="empty"><h3>Your first contribution starts here.</h3><p>Choose a mission and submit a real improvement.</p><a class="btn" href="/missions">Explore missions</a></div>}</section><section class="section"><div class="panel"><h3>Your invitation link</h3><p>30 XP when an invited builder has a reviewed and accepted contribution. No XP for a signup alone.</p><input readonly value={new URL(c.req.url).origin+'/join?ref='+u.handle} style="width:100%;padding:13px;background:#080e17;color:#c7f77a;border:1px solid #425467;border-radius:9px"/></div></section></Shell>)});
app.get('/work/:id',async c=>{
 const u=await user(c);if(!u)return c.redirect('/login');
 const id=esc(c.req.param('id'));
 const rows=await sql`SELECT w.*,s.mission_id,m.title FROM workpackets w JOIN submissions s ON s.id=w.submission_id JOIN missions m ON m.id=s.mission_id WHERE w.id=${id} AND s.user_id=${u.id} LIMIT 1`;
 if(!rows.length)return c.notFound();
 const w=rows[0],events=await sql`SELECT event_type,evidence_url,created_at FROM bridge_events WHERE workpacket_id=${id} ORDER BY created_at ASC`;
 const stages=[['triage_ready','Accepted for triage'],['leased','Execution reserved'],['dispatched','GitHub issue linked'],['implementation_ready','PR opened'],['qa_passed','CI evidence recorded'],['release_reported','Release reported'],['release_verified','Release verified'],['revalidated','Contributor revalidated']];
 const reached=w.status==='reopened'?stages.length-2:stages.findIndex(x=>x[0]===w.status);
 return c.html(<Shell u={u} active=""><div class="crumb"><a href="/profile">← My profile</a> / Development evidence</div><div class="subhero"><div class="label">YOUR CONTRIBUTION · DEVELOPMENT TRACE</div><h2>{w.title}</h2><p>Each stage requires evidence. Reviewed work is not automatically shipped code.</p><span class={'badge '+(w.status==='release_verified'?'accepted':'pending')}>{w.status.replaceAll('_',' ')}</span></div><div class="two"><div class="panel"><h3>Execution timeline</h3><div class="trace-list">{stages.map(([state,label],i)=><div class={'trace-item '+(i<=reached?'reached':'future')}><span class="trace-dot">{i<reached?'✓':String(i+1)}</span><div><strong>{label}</strong><div class="fine">{state===w.status?'Current recorded stage':i<reached?'Previously recorded stage':'Not yet evidenced'}</div></div></div>)}</div>{w.status==='reopened'&&<div class="notice bad">The contributor reported the release did not resolve the problem.</div>}{w.status==='release_verified'&&<div class="actions"><a class="btn" href={'/revalidate/'+w.id}>Revalidate release ↗</a></div>}</div><div class="panel"><h3>Recorded evidence</h3>{events.length?events.map((x:any)=><div class="evidence-row"><div class="label">{x.event_type.replaceAll('.',' · ')}</div><div class="fine">{new Date(x.created_at).toISOString()}</div>{x.evidence_url?<a class="link" href={x.evidence_url} target="_blank" rel="noopener noreferrer nofollow">Open source evidence ↗</a>:<div class="fine">No external evidence supplied.</div>}</div>):<div class="empty">No execution events have been recorded.</div>}<p class="fine">WorkPacket: {w.id}</p><p class="fine">Repository: {w.repository||'Not assigned'}</p>{w.verification_receipt_url&&<p><a class="link" href={w.verification_receipt_url} target="_blank" rel="noopener noreferrer nofollow">Independent verifier receipt ↗</a></p>}</div></div></Shell>);
});
app.get('/proof/:id',async c=>{const x=(await sql`SELECT s.*,m.title,m.category,p.title AS project,u.handle FROM submissions s JOIN missions m ON m.id=s.mission_id JOIN projects p ON p.id=m.project_id JOIN users u ON u.id=s.user_id WHERE s.id=${c.req.param('id')} AND s.status='accepted' LIMIT 1`)[0];if(!x)return c.notFound();return c.html(<Shell u={await user(c)} active=""><div class="subhero"><div class="label">PUBLIC PROOF · ACCEPTED WORK</div><h2>Proof of contribution.</h2><p>Reviewed contribution, not a claim of deployed code or production impact.</p></div><div class="panel"><div class="label">{x.project} / {x.category}</div><h3>{x.title}</h3><p>Builder: @{x.handle}</p><p><span class="badge accepted">Accepted</span> · {new Date(x.reviewed_at).toISOString().slice(0,10)}</p><p>Review: {x.reviewer_note}</p>{x.evidence_url&&<p><a class="link" href={x.evidence_url} target="_blank" rel="noopener noreferrer nofollow">Open external evidence ↗</a></p>}<div class="fine">Proof ID: {x.id}. Submission text is private by default.</div></div></Shell>)});
app.get('/community',async c=>{const ranking=await sql`SELECT u.handle,u.xp,(SELECT count(*)::int FROM submissions WHERE user_id=u.id AND status='accepted') accepted FROM users u WHERE u.xp>0 ORDER BY u.xp DESC,u.created_at LIMIT 40`,proofs=await sql`SELECT s.id,m.title,u.handle FROM submissions s JOIN users u ON u.id=s.user_id JOIN missions m ON m.id=s.mission_id WHERE s.status='accepted' ORDER BY s.reviewed_at DESC LIMIT 10`;return c.html(<Shell u={await user(c)} active="/community"><div class="subhero"><div class="label">HUMANS × AI · THE FIRST WAVE</div><h2>Builder community.</h2><p>Only actual accepted contributions are counted. No invented users or engagement metrics.</p></div><div class="two"><div class="panel"><h3>Leaderboard</h3>{ranking.length?<table class="table"><thead><tr><th>Builder</th><th>Accepted</th><th>XP</th></tr></thead><tbody>{ranking.map((r:any)=><tr><td>@{r.handle}</td><td>{r.accepted}</td><td>{r.xp}</td></tr>)}</tbody></table>:<div class="empty">The leaderboard begins with the first accepted contribution.</div>}</div><div class="panel"><h3>Verified activity</h3>{proofs.length?proofs.map((p:any)=><p><a class="link" href={'/proof/'+p.id}>@{p.handle}: {p.title}</a></p>):<div class="empty">No accepted work yet. Be among the first.</div>}<div class="actions"><a class="btn ghost" href="/join">Join Genesis ↗</a></div></div></div></Shell>)});
app.get('/activity',async c=>{
 const rows=await sql`SELECT status,count(*)::int n FROM workpackets GROUP BY status ORDER BY status`;
 const receipts=await sql`SELECT evidence_url,created_at FROM bridge_events WHERE event_type='release.verified' AND source='independent_verifier' AND evidence_url IS NOT NULL ORDER BY created_at DESC LIMIT 8`;
 const total=rows.reduce((sum:number,x:any)=>sum+x.n,0);
 const verified=rows.filter((x:any)=>['release_verified','revalidated'].includes(x.status)).reduce((sum:number,x:any)=>sum+x.n,0);
 return c.html(<Shell u={await user(c)} active="/activity"><div class="subhero"><div class="label">NETWORK ACTIVITY / EVIDENCE FIRST</div><h2>See what has actually happened.</h2><p>WorkPackets, reviews, source changes and verified releases are separate facts. This page shows recorded system activity, not estimated reach or synthetic participation.</p></div><div class="grid"><div class="panel"><div class="label">WORKPACKETS CREATED</div><div class="score">{total}</div><p>Accepted contributions queued for potential work.</p></div><div class="panel"><div class="label">VERIFIED RELEASES</div><div class="score">{verified}</div><p>Only after the independent verification transition.</p></div><div class="panel"><div class="label">GITHUB EXECUTION</div><h3>{Bun.env.BRIDGE_ENABLED==='true'?'Bridge configured':'Not yet active'}</h3><p>Activation is not equivalent to a merged release; follow the evidence timeline.</p></div></div><section class="section"><div class="sectionhead"><div><div class="label">DEVELOPMENT PIPELINE</div><h2>Recorded WorkPacket states.</h2><p>Counts are read directly from the Proofloom database.</p></div><a class="btn ghost" href="/missions">Explore missions ↗</a></div><div class="grid">{rows.length?rows.map((x:any)=><div class="panel"><div class="label">{String(x.status).replaceAll('_',' ')}</div><div class="score">{x.n}</div><p>Recorded items in this state</p></div>):<div class="empty"><h3>No WorkPackets yet</h3><p>The first accepted submission will create one. A WorkPacket is not a PR or release.</p></div>}</div></section><section class="section"><div class="sectionhead"><div><div class="label">INDEPENDENT EVIDENCE</div><h2>Verified release receipts.</h2><p>A release appears here only after an independently recorded verification event.</p></div></div>{receipts.length?<div class="panel">{receipts.map((x:any)=><div class="evidence-row"><span class="live-pill">Verified release</span><p>{new Date(x.created_at).toISOString().slice(0,10)}</p><a class="link" href={x.evidence_url} target="_blank" rel="noopener noreferrer nofollow">Open verification receipt ↗</a></div>)}</div>:<div class="empty"><h3>No independently verified release yet.</h3><p>Review acceptance, GitHub code and production verification are tracked separately. No evidence is invented to fill this state.</p></div>}</section></Shell>);
});
app.get('/studio',async c=>{
 const u=await user(c);
 const previous=u?await sql`SELECT status,reviewer_note FROM submissions WHERE user_id=${u.id} AND mission_id='q05' LIMIT 1`:[];
 return c.html(<Shell u={u} active="/studio"><div class="subhero"><div class="label">VIBE STUDIO / BUILD WITH CLARITY</div><h2>Turn your prompt into real work.</h2><p>Describe a product improvement with a clear goal, observable behavior and acceptance tests. Submit the proposal to Proofloom's genuine review queue.</p></div><div class="two"><div class="panel"><div class="label">YOUR WORKBENCH</div><h3>Compose a review-ready proposal</h3><p>Clear objectives are more valuable than long, vague prompts. Describe what you want changed and how success can be tested.</p>{previous.length&&previous[0].status!=='changes_requested'?<div class="notice">You already submitted this mission. Current status: {previous[0].status}. <a class="link" href="/profile">View your submission ↗</a></div>:u?<form action="/submit" method="post"><input type="hidden" name="mission_id" value="q05"/><div class="field"><label for="studio-prompt">Your proposed improvement</label><textarea id="studio-prompt" name="body" required minlength="25" maxlength="6000" placeholder={'Goal: Improve the first-time builder experience.\nCurrent behavior: Describe exactly where users get stuck.\nProposed change: State the new UI or logic.\nAcceptance checks: Include a pass and a failure scenario.'}></textarea><div class="fine">25–6,000 characters. Your contribution is stored and reviewed, not executed as code.</div></div><div class="field"><label for="studio-evidence">Evidence URL (optional)</label><input id="studio-evidence" type="url" name="evidence" placeholder="https://github.com/..."/></div><button type="submit" class="btn">Submit for human review ↗</button></form>:<div class="actions"><a class="btn" href="/join">Join to start writing ↗</a><a class="btn ghost" href="/login">Already a member? Log in</a></div>}</div><div class="panel"><div class="label">PROOF, NOT HYPE</div><h3>How your work moves forward</h3><div class="trace-list"><div class="trace-item reached"><span class="trace-dot">01</span><div><strong>Create a specific proposal</strong><div class="fine">Describe change, expected behavior and evidence.</div></div></div><div class="trace-item reached"><span class="trace-dot">02</span><div><strong>Independent human review</strong><div class="fine">Accepted submissions receive nonfinancial XP and a WorkPacket.</div></div></div><div class="trace-item future"><span class="trace-dot">03</span><div><strong>GitHub execution where authorized</strong><div class="fine">Actual issue, PR and CI evidence are separate stages.</div></div></div><div class="trace-item future"><span class="trace-dot">04</span><div><strong>Verified release</strong><div class="fine">Never reported without an observed deployment and verification receipt.</div></div></div></div><a class="link" href="/mission/q05">Read the full prompt mission ↗</a></div></div></Shell>);
});
app.get('/academy',async c=>c.html(<Shell u={await user(c)} active="/academy"><div class="subhero"><div class="label">LEARN TO BUILD</div><h2>Learn by doing.</h2><p>A practical progression from exploration to real professional work.</p></div><div class="grid">{[['00','Explorer','Test a product and document a real issue.','q01'],['01','Prompt Builder','Translate ideas into precise AI coding prompts.','q05'],['02','Vibe Developer','Improve interfaces and explain your design.','q03'],['03','Collaborator','Submit a reviewed implementation.','q10'],['04','Professional','Build verified portfolio evidence.','q10'],['05','Maintainer','Help define fair review standards.','q09']].map(([n,t,d,q])=><a class="card" href={'/mission/'+q}><div class="meta">LEVEL {n}</div><h3>{t}</h3><p>{d}</p><div class="bottom">Start practice <span class="arrow">↗</span></div></a>)}</div></Shell>));
app.get('/opportunities',async c=>c.html(<Shell u={await user(c)} active="/opportunities"><div class="subhero"><div class="label">WORK · BOUNTIES · COLLABORATE</div><h2>Earn opportunities through work.</h2><p>Your verified portfolio is the starting point. Paid listings go live only after sponsor funding and terms exist.</p></div><div class="two"><div class="panel"><h3>Funded opportunities</h3><div class="empty">No external bounty has confirmed funding yet.</div></div><div class="panel"><h3>Have a mission?</h3><p>Tell us what you want to build or test with a community of human and AI builders.</p><a class="btn" href="/sponsors">Sponsor a mission ↗</a></div></div></Shell>));
app.get('/rewards',async c=>c.html(<Shell u={await user(c)} active="/rewards"><div class="subhero"><div class="label">CONTRIBUTION ECONOMY</div><h2>Earn what you prove.</h2><p>XP, token distributions and cash payments are separate. You can participate without buying anything.</p></div><div class="grid"><div class="panel"><div class="label">LIVE · NONFINANCIAL</div><h3>Verified XP</h3><p>Nontransferable, off-chain recognition granted after accepted work.</p><a class="link" href="/profile">Your balance</a></div><div class="panel"><div class="label">DESIGN · NOT ISSUED</div><h3>Ecosystem token</h3><p>Draft economics are public, but no token has been created or offered for sale by this app.</p><a class="link" href="/whitepaper">Tokenomics</a></div><div class="panel"><div class="label">NOT YET FUNDED</div><h3>USDC bounties</h3><p>Cash rewards and sponsor-funded work will activate with verified funding and terms.</p><a class="link" href="/sponsors">Sponsor intake</a></div></div></Shell>));
app.get('/sponsors',async c=>c.html(<Shell u={await user(c)} active=""><div class="subhero"><div class="label">FOR PROJECT SPONSORS</div><h2>Turn a problem into a mission.</h2><p>Describe a scoped improvement. Submitting an inquiry does not commit money or create a paid bounty.</p></div><div class="two"><div class="panel"><form action="/sponsor" method="post"><div class="field"><label>Contact name</label><input name="name" maxlength="120" required/></div><div class="field"><label>Work email</label><input type="email" name="email" maxlength="200" required/></div><div class="field"><label>Organization / project</label><input name="project" maxlength="180" required/></div><div class="field"><label>Indicative budget</label><select name="budget"><option>Exploring</option><option>US$100–499</option><option>US$500–1,999</option><option>US$2,000+</option></select></div><div class="field"><label>What do you want improved?</label><textarea name="description" minlength="25" maxlength="3000" required></textarea></div><button class="btn">Send sponsor inquiry ↗</button></form></div><div class="panel"><h3>Sponsor journey</h3><p>01 · Define objective and deliverables.</p><p>02 · Confirm funding and work terms.</p><p>03 · Publish mission to eligible builders.</p><p>04 · Review deliverables and account for payouts.</p><p class="fine">Sponsor intake is active. Checkout and payout processing are not connected.</p></div></div></Shell>));
app.post('/sponsor',async c=>{if(!sameOrigin(c))return c.text('Forbidden',403);if(!await allowed(c,'sponsor',5,86400))return c.text('Rate limit',429);const b=await c.req.parseBody(),name=esc(b.name),email=esc(b.email),project=esc(b.project),budget=esc(b.budget),description=esc(b.description);if(name.length<2||name.length>120||!email.includes('@')||project.length<2||description.length<25||description.length>3000)return c.text('Invalid details',400);await sql`INSERT INTO sponsor_leads(id,name,email,project,budget,description) VALUES(${crypto.randomUUID()},${name},${email},${project},${budget},${description})`;return c.redirect('/?notice='+qp('Inquiry saved. No payment collected.'))});
app.get('/whitepaper',async c=>c.html(<Shell u={await user(c)} active=""><div class="subhero"><div class="label">WORKING WHITEPAPER · GENESIS</div><h2>Software built by everyone.</h2><p>A contribution economy powered by humans, AI builders and measurable product progress.</p></div><div class="panel prose"><h3>01 · Thesis</h3><p>Everyone can improve software. A useful bug report, reproducible test or precise prompt can create real development work. Quality matters more than prompt volume.</p><h3>02 · Core mechanism</h3><p>Discover → Join → Contribute → Verify → Improve → Reward → Grow. The Genesis beta implements accounts, mission discovery, submission persistence, human review, XP and public accepted-work proofs. Agent execution is a future integration.</p><h3>03 · Contribution proof</h3><p>Each accepted record identifies the project, task, contributor, review decision and supporting evidence link when provided. Acceptance alone does not certify a production release.</p><h3>04 · Token economy hypothesis</h3><p>Provisional maximum supply: 1,000,000,000. Community and verified contributors 45%; ecosystem development and sponsors 15%; treasury 12%; liquidity and market development 10%; core team 12%; strategic reserve 6%. These allocations are design assumptions, not issued tokens or present entitlements.</p><h3>05 · Sustainability</h3><p>Potential revenue: sponsored missions, 5–10% marketplace fees on eligible bounties, 10% on completed freelancer work, sponsor workspaces and usage-based AI credits. No revenue or paid transaction is claimed.</p><h3>06 · Technology roadmap</h3><p>Independent tenant-aware data → GitHub repository adapters → WorkPacket-based AI execution → independent QA receipts → release revalidation → funded rewards and optional EVM distribution. External projects can use the platform without adopting the Founder's internal operating systems.</p><h3>07 · Genesis status</h3><p>Production implementation status must be independently checked. The application does not issue tokens, guarantee token value or display hypothetical liquidity as live.</p><h3>08 · Independence</h3><p>Proofloom is an independent project. Noetfield, ARQANT, BuildRelay, WorkforceOS, SignalForge, Cairn and Earnloop are not merged into it. Any future integrations require authorized project-level adapters.</p></div></Shell>));
app.get('/privacy',async c=>c.html(<Shell u={await user(c)} active=""><div class="subhero"><div class="label">GENESIS BETA · PRIVACY</div><h2>Privacy notice.</h2></div><div class="panel prose"><h3>What we collect</h3><p>Email, public handle, protected password hash, optional referral, submissions, evidence links, review outcomes, XP, and sponsor inquiries. Data lives in this venture's isolated Railway PostgreSQL.</p><h3>Public and private</h3><p>Handles, XP, and accepted proof records can be public. Email and full submissions are restricted to authorized operators. Never submit secrets, confidential code, or sensitive personal data.</p><h3>Controls and changes</h3><p>Sessions use secure HTTP-only cookies, passwords are hashed, and review access is restricted. No wallets or payments are active. Data export and deletion support and formal operator contact details must be finalized before wider scale.</p></div></Shell>));
app.get('/terms',async c=>c.html(<Shell u={await user(c)} active=""><div class="subhero"><div class="label">GENESIS BETA · TERMS</div><h2>Participation terms.</h2></div><div class="panel prose"><p>Submit only work and evidence you have the right to share. Do not upload secrets, unauthorized third-party code or abusive content. Proofloom may assess or reject contributions on evidence and quality criteria.</p><p>Your feedback may be used to improve the relevant project; source-code licensing follows the connected repository's actual license and contribution terms. No third-party copyright is transferred automatically.</p><p>XP is nontransferable recognition, not money or a token right. No token distribution, income, hiring, or paid work is promised by joining this beta.</p></div></Shell>));
app.get('/operator',async c=>c.html(<Shell u={await user(c)} active="" notice={c.req.query('notice')}><div class="subhero"><div class="label">PRIVATE OPERATIONS</div><h2>Contribution review.</h2><p>Enter the review secret stored in this Railway service's environment. Never share the secret with participants.</p></div><div class="two"><div class="panel"><form action="/operator/queue" method="post"><div class="field"><label>Operator review key</label><input type="password" name="key" minlength="32" required/></div><button class="btn">Open queue ↗</button></form></div><div class="panel"><h3>Verification boundary</h3><p>Accepting a contribution creates a triage-ready WorkPacket reference and awards XP once; it does not represent an AI run, PR, merge or deployed release.</p></div></div></Shell>));
app.post('/operator/queue',async c=>{
 if(!sameOrigin(c))return c.text('Forbidden',403);
 if(!await allowed(c,'operator',25,3600))return c.text('Rate limited',429);
 const b=await c.req.parseBody();if(!adminKey(esc(b.key)))return c.text('Unauthorized',403);
 const token=crypto.randomUUID()+'.'+crypto.randomUUID();await sql`INSERT INTO operator_sessions(token_hash,expires_at) VALUES(${digest(token)},now()+interval '2 hours')`;
 setCookie(c,OPER_COOKIE,token,{httpOnly:true,secure:true,sameSite:'Strict',path:'/',maxAge:7200});return c.redirect('/operator/queue');
});
app.get('/operator/queue',async c=>{
 if(!await operatorSession(c))return c.redirect('/operator');
 const queue=await sql`SELECT s.*,m.title,m.xp,u.handle FROM submissions s JOIN missions m ON m.id=s.mission_id JOIN users u ON u.id=s.user_id WHERE s.status='pending' ORDER BY s.created_at LIMIT 100`;
 const packets=await sql`SELECT w.id,w.status,w.updated_at,w.repository,w.artifact_url,w.qa_evidence_url,w.release_url,m.title,s.id AS submission_id FROM workpackets w JOIN submissions s ON s.id=w.submission_id JOIN missions m ON m.id=s.mission_id ORDER BY w.updated_at DESC LIMIT 30`;
 return c.html(<Shell u={await user(c)} active=""><div class="subhero"><div class="label">REVIEW QUEUE · AGENT WORKPACKETS</div><h2>{queue.length} pending.</h2><p>Authorization-aware review. XP and execution are tracked separately.</p><form action="/operator/logout" method="post"><button class="btn ghost">Lock operator console</button></form></div>{queue.length?queue.map((x:any)=><div class="panel" style="margin:14px 0"><div class="label">@{x.handle} · {x.title}</div><p style="white-space:pre-wrap">{x.body}</p>{x.evidence_url&&<p><a class="link" href={x.evidence_url} rel="noopener noreferrer nofollow" target="_blank">Evidence ↗</a></p>}<form action="/operator/review" method="post"><input type="hidden" name="id" value={x.id}/><div class="field"><label>Decision</label><select name="status"><option value="accepted">Accept ({x.xp} XP)</option><option value="changes_requested">Changes requested</option><option value="rejected">Reject</option></select></div><div class="field"><label>Evidence-based review note</label><textarea name="note" minlength="8" maxlength="1500" required></textarea></div><button class="btn">Record decision ↗</button></form></div>):<div class="empty">No pending submissions.</div>}<section class="section"><h2>Agent bridge queue</h2><div class="panel"><p>GitHub repository: {bridgeRepository()?'Repository allowlist configured':'No repository allowlist'} · Automatic execution: {Bun.env.BRIDGE_ENABLED==='true'&&!!bridgeRepository()?'Queue leasing enabled':'Not enabled'}</p><table class="table"><thead><tr><th>Task</th><th>Status</th><th>Evidence</th><th>Updated</th></tr></thead><tbody>{packets.map((x:any)=><tr><td>{x.title}<div class="fine">{x.id}</div></td><td><span class="badge">{x.status}</span></td><td>{x.artifact_url?<a class="link" href={x.artifact_url} target="_blank" rel="noopener noreferrer nofollow">PR ↗</a>:'—'} {x.qa_evidence_url?<a class="link" href={x.qa_evidence_url} target="_blank" rel="noopener noreferrer nofollow">CI ↗</a>:''} {x.release_url?<a class="link" href={x.release_url} target="_blank" rel="noopener noreferrer nofollow">Release ↗</a>:''}</td><td>{new Date(x.updated_at).toISOString().slice(0,16)}</td></tr>)}</tbody></table></div></section></Shell>);
});
