app.post('/operator/review',async c=>{if(!sameOrigin(c))return c.text('Forbidden',403);const b=await c.req.parseBody(),key=esc(b.key),id=esc(b.id),status=esc(b.status),note=esc(b.note);if(!await operatorAllowed(c,key))return c.text('Unauthorized',403);if(!['accepted','changes_requested','rejected'].includes(status)||note.length<8||note.length>1500)return c.text('Invalid review',400);try{await sql.begin(async tx=>{const r=await tx`SELECT s.*,m.xp,m.project_id,u.referred_by,u.referral_awarded FROM submissions s JOIN missions m ON m.id=s.mission_id JOIN users u ON u.id=s.user_id WHERE s.id=${id} FOR UPDATE OF s`;if(!r.length||r[0].status!=='pending')throw Error('Already reviewed or not found');const x=r[0];await tx`UPDATE submissions SET status=${status},reviewer_note=${note},reviewed_at=now() WHERE id=${id}`;await bridgeEvent(tx,id,null,x.project_id,'review.'+status,'review:'+id+':'+status);if(status==='accepted'){await tx`INSERT INTO reward_events(id,user_id,submission_id,kind,xp) VALUES(${crypto.randomUUID()},${x.user_id},${id},'accepted',${x.xp})`;await tx`UPDATE users SET xp=xp+${x.xp} WHERE id=${x.user_id}`;const packetId=crypto.randomUUID();await tx`INSERT INTO workpackets(id,submission_id,project_id) VALUES(${packetId},${id},${x.project_id}) ON CONFLICT(submission_id) DO NOTHING`;
 await bridgeEvent(tx,id,packetId,x.project_id,'workpacket.created','packet:'+id);
 await bridgeEvent(tx,id,packetId,x.project_id,'contribution.accepted','accepted:'+id);if(x.referred_by&&!x.referral_awarded){const a=await tx`UPDATE users SET referral_awarded=true WHERE id=${x.user_id} AND referral_awarded=false RETURNING id`;if(a.length){await tx`INSERT INTO reward_events(id,user_id,kind,xp) VALUES(${crypto.randomUUID()},${x.referred_by},'qualified_referral',30)`;await tx`UPDATE users SET xp=xp+30 WHERE id=${x.referred_by}`}}}});return c.redirect('/operator?notice='+qp('Decision persisted.'));}catch(e:any){return c.text(e.message||'Review failed',409)}});

