// Explicitly gated test-only HTTP harness. Creates and deletes synthetic accounts.
// It never reports synthetic accounts as real signups and does not transfer funds.
app.post('/__e2e',async c=>{
 if(Bun.env.QA_ENABLED!=='true')return c.text('Not found',404);
 if(!await allowed(c,'e2e',2,86400))return c.json({ok:false,error:'rate_limited'},429);
 const origin=new URL(c.req.url).origin;
 const suffix=crypto.randomUUID().replace(/-/g,'').slice(0,12);
 const emailA='proofloom-e2e-parent-'+suffix+'@example.invalid',emailB='proofloom-e2e-child-'+suffix+'@example.invalid';
 const handleA='qa_parent_'+suffix,handleB='qa_child_'+suffix,password='QA-Password-'+crypto.randomUUID();
 const steps:{name:string,pass:boolean}[]=[];
 const record=(name:string,pass:boolean)=>{steps.push({name,pass});if(!pass)throw Error(name)};
 const submit=async(path:string,fields:Record<string,string>,cookie?:string)=>app.request(new Request(origin+path,{method:'POST',headers:{'content-type':'application/x-www-form-urlencoded','origin':origin,...(cookie?{cookie}:{})},body:new URLSearchParams(fields)}));
 let accounts:string[]=[];let resultOk=false;
 try{
 const parent=await submit('/register',{email:emailA,handle:handleA,password,agree:'yes'});record('Parent signup',parent.status===302);
 const parentCookie=(parent.headers.get('set-cookie')||'').split(';')[0];record('Parent session',parentCookie.startsWith(COOKIE+'='));
 const child=await submit('/register',{email:emailB,handle:handleB,password,ref:handleA,agree:'yes'});record('Child referral signup',child.status===302);
 const childCookie=(child.headers.get('set-cookie')||'').split(';')[0];record('Child session',childCookie.startsWith(COOKIE+'='));
 const parents=await sql`SELECT id,xp FROM users WHERE email=${emailA}`,children=await sql`SELECT id,xp,referred_by FROM users WHERE email=${emailB}`;
 accounts=[...parents.map(x=>x.id),...children.map(x=>x.id)];record('Referral persists but grants no signup XP',parents.length===1&&children.length===1&&parents[0].xp===0&&children[0].xp===0&&children[0].referred_by===parents[0].id);
 const posted=await submit('/submit',{mission_id:'q01',body:'QA test steps: enter mission q01, submit this reproducible, valid feedback, and verify review is required for XP.'},childCookie);
 record('Contribution accepted by API',posted.status===302);
 const subs=await sql`SELECT id,status FROM submissions WHERE user_id=${children[0].id}`;record('Pending contribution persisted',subs.length===1&&subs[0].status==='pending');
 const duplicate=await submit('/submit',{mission_id:'q01',body:'Another contribution must be prevented for this mission.'},childCookie);
 const count=await sql`SELECT count(*)::int n FROM submissions WHERE user_id=${children[0].id}`;record('Duplicate submission prevented',duplicate.status===302&&count[0].n===1);
 const review=await submit('/operator/review',{key:Bun.env.OPERATOR_REVIEW_KEY||'',id:subs[0].id,status:'accepted',note:'QA accepted reproducible documentation for technical integration test.'});
 record('Operator review accepted',review.status===302);
 const xp=await sql`SELECT id,xp FROM users WHERE id IN (${parents[0].id},${children[0].id})`;
 record('XP and referral awarded once',xp.find(x=>x.id===parents[0].id)?.xp===30&&xp.find(x=>x.id===children[0].id)?.xp===45);
 const ledger=await sql`SELECT count(*)::int n FROM reward_events WHERE submission_id=${subs[0].id}`;record('Unique reward ledger',ledger[0].n===1);
 const proof=await app.request(new Request(origin+'/proof/'+subs[0].id));record('Proof accessible',proof.status===200);
 const packets=await sql`SELECT status FROM workpackets WHERE submission_id=${subs[0].id}`;record('WorkPacket persisted as triage ready',packets.length===1&&packets[0].status==='triage_ready');
 const repeat=await submit('/operator/review',{key:Bun.env.OPERATOR_REVIEW_KEY||'',id:subs[0].id,status:'accepted',note:'Duplicate approval must not award XP again.'});record('Repeat review blocked',repeat.status===409);
 const userExport=await app.request(new Request(origin+'/api/v1/account/export',{headers:{cookie:childCookie}}));record('Own data export works',userExport.status===200);
 const deleted=await submit('/account/delete',{password,confirm:'DELETE'},childCookie);record('Password-confirmed account deletion',deleted.status===302);
 const leftover=await sql`SELECT count(*)::int n FROM users WHERE id=${children[0].id}`;record('Child account and contributions deleted',leftover[0].n===0);
 resultOk=true;
 }catch(e:any){console.error('e2e_failure',e?.message)}finally{
   // Cleanup all possible test rows even if an earlier step failed.
   const ids=await sql`SELECT id FROM users WHERE email IN (${emailA},${emailB})`;
   try{for(const rec of ids){const id=rec.id;await sql.begin(async tx=>{
     await tx`UPDATE users SET referred_by=null WHERE referred_by=${id}`;
     await tx`DELETE FROM bridge_events WHERE submission_id IN (SELECT id FROM submissions WHERE user_id=${id})`;
     await tx`DELETE FROM workpackets WHERE submission_id IN (SELECT id FROM submissions WHERE user_id=${id})`;
     await tx`DELETE FROM reward_events WHERE user_id=${id} OR submission_id IN (SELECT id FROM submissions WHERE user_id=${id})`;
     await tx`DELETE FROM submissions WHERE user_id=${id}`;
     await tx`DELETE FROM sessions WHERE user_id=${id}`;
     await tx`DELETE FROM users WHERE id=${id}`;
   });}}catch(e:any){resultOk=false;console.error('e2e_cleanup_failure',e?.message)}
   const remainder=await sql`SELECT count(*)::int n FROM users WHERE email IN (${emailA},${emailB})`;
   record('Synthetic users removed',remainder[0].n===0);
 }
 const ok=resultOk&&steps.every(x=>x.pass);
 if(!ok)console.error('proofloom_e2e_failed',JSON.stringify({steps}));
 return c.json({ok,steps,synthetic_users_retained:false},ok?200:503);
});
app.post('/__smoke',async c=>{if(!await allowed(c,'smoke',8,3600))return c.json({error:'rate_limited'},429);const checks=[];for(const path of ['/','/missions','/join','/studio','/community','/academy','/opportunities','/rewards','/sponsors','/whitepaper','/api/v1/status','/api/v1/missions','/api/v1/bridge/status','/privacy','/terms']){const response=await app.request(new Request('https://proofloom.local'+path));const body=await response.text();checks.push({path,status:response.status,nonempty:body.length>(path.startsWith('/api/')?20:150)})}let dbCheck={pass:false,detail:'not_started'};
try{let wrote=false;try{await sql.begin(async tx=>{const testId=crypto.randomUUID(),userId=crypto.randomUUID(),handle='rollback_'+testId.replace(/-/g,'').slice(0,12),email=handle+'@example.invalid';
 await tx`INSERT INTO users(id,email,handle,password_hash) VALUES(${userId},${email},${handle},'unused-qa-rollback')`;
 await tx`INSERT INTO submissions(id,mission_id,user_id,body) VALUES(${testId},'q01',${userId},'Rollback-only transaction validation; no data retained.')`;
 const packetId=crypto.randomUUID();await tx`INSERT INTO workpackets(id,submission_id,project_id) VALUES(${packetId},${testId},'proofloom-lab')`;
 await bridgeEvent(tx,testId,packetId,'proofloom-lab','qa.rollback','qa:'+testId);
 const r=await tx`SELECT count(*)::int n FROM bridge_events WHERE workpacket_id=${packetId}`;wrote=r[0].n===1;if(!wrote)throw Error('rollback_check_incomplete');throw Error('QA_ROLLBACK_EXPECTED');});
}catch(e:any){if(e.message!=='QA_ROLLBACK_EXPECTED')throw e;}dbCheck={pass:wrote,detail:'transaction_rolled_back'};
}catch(e:any){dbCheck={pass:false,detail:e.message?.slice(0,100)||'error'};}
const ok=checks.every(x=>x.status===200&&x.nonempty)&&dbCheck.pass;if(!ok)console.error('proofloom_smoke_failed',JSON.stringify({checks,dbCheck}));return c.json({status:ok?'pass':'fail',checks,db_write_rollback:dbCheck},ok?200:503)});

// Read-only, no secrets or synthetic accounts: validates translated live HTML routes in every enabled locale.
app.post('/__i18n_smoke',async c=>{
 if(!await allowed(c,'i18n-smoke',6,3600))return c.json({status:'rate_limited'},429);
 const cases=[];
 for(const lang of ['en','fa','ar','es','fr','de','pt-BR','ru','zh-CN','hi'] as const){
  for(const path of ['/','/missions','/join','/mission/q01','/privacy','/terms']){
   const response=await app.request(new Request('https://proofloom.local'+path+'?lang='+lang));
   const text=await response.text();
   const dir=['fa','ar'].includes(lang)?'rtl':'ltr';
   const localeOk=text.includes('<html lang="'+lang+'" dir="'+dir+'">');
   const chooserOk=text.includes('value="'+lang+'" selected');
   const noStaleLanguage=text.includes('name="return_to" value="'+path+'"');
   const map=translations[lang];
   const marker=path==='/missions'?'Open missions.':path==='/mission/q01'?'Make the first minute clearer':path==='/privacy'?'Privacy notice.':path==='/terms'?'Participation terms.':path==='/join'?'Create your builder identity.':'Build it.';
   const translated=lang==='en'?true:text.includes(map?.[marker]||'__missing_dictionary_marker__');
   cases.push({lang,path,status:response.status,langTag:localeOk,selector:chooserOk,translated,cleanReturn:noStaleLanguage});
  }
 }
 const failed=cases.filter(x=>x.status!==200||!x.langTag||!x.selector||!x.translated||!x.cleanReturn);
 if(failed.length)console.error('i18n_smoke_failed',JSON.stringify(failed));
 return c.json({status:failed.length?'fail':'pass',checked:cases.length,localeCount:10,failures:failed},failed.length?503:200);
});

